int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_xDistBuf;
float4 amzSample_xDistBuf(float2 uv) { return float4(amzt_xDistBuf.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_xDistBuf(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_b0size;
layout(color) uniform half4 amzp_b0color;
uniform float amzp_b0direction;
uniform float amzp_alpha;
uniform float amzp_fill;
uniform float amzp_offset;
uniform float amzp_fade;
        float2 encodeFloat(float v) {
             float2 enc = fract(float2(1.0, 255.0)*v);
            enc.x -= enc.y/255.0;
            return enc;
        }
        float decodeFloat(float2 v) {
            return dot(v,float2(1.0,1.0/255.0));
        }
        struct Border {
            int direction;
            float amzLocal_size;
            float4 color;
        };
        void amzRender() {
            float radius= (35.0+amzp_offset)*1.0;
            int from = -amzIntMax(1,int(radius));
            int to = amzIntMax(1,int(radius));
            float px = (1.0/(screen.zw/1.0).x);
            float py = (1.0/(screen.zw/1.0).y);
            if( amzPass==0 ) {
                float nearestOutside = 100.0;
                float nearestInside = 100.0;
                for(int i=from; i<to; i++ ) {
                    float x = float(i);
                    float4 sample = amzTexture(0,float2(amzScreenNorm().s + x*(px/1.0),amzScreenNorm().t));
                    float xdistOut = sample.a > 0.0 ? abs(x) : radius*2.0;
                    float xdistIn = sample.a < 0.003 ? abs(x) : radius*2.0;
                    nearestOutside = min(nearestOutside,xdistOut);
                    nearestInside = min(nearestInside,xdistIn);
                }
                amzOutput = float4(encodeFloat(nearestOutside/100.0),encodeFloat(nearestInside/100.0));
            } else {
                float nearestOutside = 100.0;
                float nearestInside = 100.0;
                for(int i=from; i<to; i++ ) {
                    float y = float(i);
                    float4 sample = amzTexture(1,float2(amzScreenNorm().s,amzScreenNorm().t + y*(py/1.0)));
                    float xdistOut = decodeFloat(sample.rg) * 100.0;
                    float xdistIn = decodeFloat(sample.ba) * 100.0;
                    float ydist = abs(y);
                    float distOut = length(float2(xdistOut,ydist));
                    float distIn = length(float2(xdistIn,ydist));
                    nearestInside = min(nearestInside,distIn);
                    nearestOutside = min(nearestOutside,distOut);
                }
                float nearestMid = max(nearestInside, nearestOutside);
                float4 original = amzTexture(0,amzScreenNorm().st);
                Border borders[1];
                borders[0].direction = int(amzp_b0direction);
                borders[0].amzLocal_size = amzp_b0size;
                borders[0].color = amzp_b0color;
                original *= amzp_fill;
                float4 result = original;
                for( int i=0; i<1; i++ ) {
                    int direction = borders[i].direction;
                    float4 color = borders[i].color*amzp_alpha;
                    float amzLocal_size = borders[i].amzLocal_size;
                    float aa = 1./amzLocal_size/2.;
                    float p = clamp((nearestOutside-amzp_offset) / amzLocal_size,0.,1.);
                    float mask;
                if( (amzp_fade>0.5) ) {
                    mask = smoothstep(1.,0.,p) * smoothstep(0.,aa,p);
                } else {
                    mask = smoothstep(0.,aa,p) * smoothstep(1., 1.-aa, p);
                }
                    if( amzLocal_size > 0.003 ) {
                        if( direction == -1 ) {
                            float4 c = mix(color, float4(0.0), smoothstep(1.0-1.5/amzLocal_size,1.0,nearestInside/(amzLocal_size/1.0))) * original.a;
                            result = c + result*(1.0-c.a);
                        } else if (direction == 0) {
                            float4 c = mix(color, float4(0.0), smoothstep(1.0-1.5/amzLocal_size,1.0,nearestMid/(amzLocal_size/1.0)));;
                            result = c + result*(1.0-c.a);
                        } else if (direction == 1) {
                            float4 c = mix(color, float4(0.0), smoothstep(1.0-1.5/amzLocal_size,1.0,nearestOutside/(amzLocal_size/1.0))) * (1.-original.a);
                            result = result + c*(1.0-result.a)*mask;
                        }
                    }
                }
                amzOutput = result;
            }
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

